class DriveWave(Drive):
    """Drive to generate a wave according to an Import object

    Attributes
    ----------
    wave : Import or None
        Wave generator
        Default: Import()
    """

    wave: Import = Field(default_factory=lambda: Import())
    """Wave generator"""

    _package: ClassVar[str] = "Simulation"
    """Name of the package of the legacy class module"""

    # Inlined from Methods.Simulation.DriveWave.get_wave
    def get_wave(self, output: Output | None = None) -> DataTime:
        """Return the wave generated by the Drive

        Parameters
        ----------
        self : DriveWave
            A DriveWave object
        output : Output, optional
            Output of the simulation (default: the fourth parent, Output.Simulation.Electrical.EEC.Drive)

        Returns
        -------
        wave : DataTime
            Voltage / current waveform (Nt, qs)
        """

        wave = self.wave.get_data()

        Phase = Data1D(
            name="phase",
            unit="",
            values=np.array(gen_name(wave.shape[0])),
            is_components=True,
        )
        # Ouput.Simulation.Electrical.EEC.Drive
        output = container_or_parent(self, output, "output", depth=4)
        if (
            output is not None
            and output.elec.time is not None
            and len(output.elec.time) > 1
        ):
            Time = Data1D(name="time", unit="s", values=output.elec.time)
        else:
            Nt = wave.shape[1]
            Time = DataLinspace(
                name="time",
                unit="s",
                symmetries={},
                initial=0,
                final=Nt,
                number=Nt,
                include_endpoint=False,
            )

        if self.is_current:
            return DataTime(
                name="Current", unit="A", symbol="I", axes=[Phase, Time], values=wave
            )
        else:
            return DataTime(
                name="Voltage", unit="V", symbol="U", axes=[Phase, Time], values=wave
            )
